CREATE TABLE "challenges" (
	"seq" bigint GENERATED BY DEFAULT AS IDENTITY (sequence name "challenges_seq_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"id" text PRIMARY KEY NOT NULL,
	"token_hash" text NOT NULL,
	"link_token_hash" text,
	"status" text NOT NULL,
	"company_name" text NOT NULL,
	"contact_name" text,
	"email" text NOT NULL,
	"phone" text,
	"outlets" integer,
	"erp_system" text,
	"gstin" text,
	"consent_at" timestamp(3) with time zone NOT NULL,
	"ai_provider" text,
	"invoices_submitted" integer DEFAULT 0 NOT NULL,
	"invoices_processed" integer DEFAULT 0 NOT NULL,
	"invoices_failed" integer DEFAULT 0 NOT NULL,
	"record_files" integer DEFAULT 0 NOT NULL,
	"records_json" text DEFAULT '{}' NOT NULL,
	"cleared" integer DEFAULT 0 NOT NULL,
	"attention" integer DEFAULT 0 NOT NULL,
	"total_invoice_paise" bigint,
	"review_value_paise" bigint,
	"findings_json" text DEFAULT '{}' NOT NULL,
	"checks_started_at" timestamp(3) with time zone,
	"completed_at" timestamp(3) with time zone,
	"report_generated_at" timestamp(3) with time zone,
	"report_downloads" integer DEFAULT 0 NOT NULL,
	"report_downloaded_at" timestamp(3) with time zone,
	"email_status" text DEFAULT 'not_sent' NOT NULL,
	"email_sent_at" timestamp(3) with time zone,
	"interest" text DEFAULT 'none' NOT NULL,
	"interest_at" timestamp(3) with time zone,
	"follow_up" text DEFAULT 'new' NOT NULL,
	"expires_at" timestamp(3) with time zone NOT NULL,
	"purged_at" timestamp(3) with time zone,
	"created_at" timestamp(3) with time zone NOT NULL,
	"updated_at" timestamp(3) with time zone NOT NULL,
	CONSTRAINT "challenges_token_hash_unique" UNIQUE("token_hash"),
	CONSTRAINT "challenges_link_token_hash_unique" UNIQUE("link_token_hash"),
	CONSTRAINT "challenges_status" CHECK ("challenges"."status" IN ('collecting', 'checking', 'complete', 'purged')),
	CONSTRAINT "challenges_email_status" CHECK ("challenges"."email_status" IN ('not_sent', 'sent', 'failed', 'not_configured')),
	CONSTRAINT "challenges_interest" CHECK ("challenges"."interest" IN ('none', 'walkthrough', 'pilot')),
	CONSTRAINT "challenges_follow_up" CHECK ("challenges"."follow_up" IN ('new', 'contacted', 'walkthrough_booked', 'pilot', 'customer', 'closed'))
);
